<template>
  <section class="live-ratings" aria-label="Đánh giá khóa học từ cơ sở dữ liệu">
    <header><div><h3>Đánh giá khóa học</h3><p>Phản hồi của học viên đã hoàn thành · dữ liệu thực</p></div><Star :size="21"/></header>
    <div class="rating-filters"><label>Khóa học đánh giá<select v-model="courseId"><option value="">Tất cả khóa trong phạm vi quản lý</option><option v-for="course in options" :key="course.courseId" :value="course.courseId">{{ course.courseName }}</option></select></label><button class="btn btn-secondary" :aria-pressed="lowOnly" @click="lowOnly=!lowOnly;page=0">{{ lowOnly?'Hiện tất cả phản hồi':'Lọc phản hồi 1–2 sao' }}</button></div>
    <p class="scope-note">Báo cáo này tổng hợp toàn bộ đánh giá đã lưu và dùng bộ lọc khóa học riêng ở trên.</p>
    <button v-if="report" class="btn btn-secondary" @click="exportCsv">CSV đánh giá theo khóa</button>
    <SkeletonLoader v-if="loading" label="Đang tải đánh giá khóa học">
      <SkeletonLoader plain variant="stats" :rows="3" />
      <SkeletonLoader plain variant="table" :rows="4" :columns="4" />
    </SkeletonLoader>
    <div v-else-if="error" class="rating-error" role="alert">{{ error }} <button class="btn btn-secondary" @click="load">Thử lại</button></div>
    <template v-else-if="report">
      <div class="live-kpis"><div><span>Điểm trung bình</span><strong>{{ report.average===null?'—':`${report.average.toFixed(1)}/5` }}</strong><small>{{ report.count }} đánh giá</small></div><div><span>Tỷ lệ phản hồi</span><strong>{{ report.responseRate===null?'—':`${Math.round(report.responseRate)}%` }}</strong><small>{{ report.count }} / {{ report.completed }} lượt học có ghi nhận hoàn thành</small></div><div><span>Phản hồi 1–2 sao</span><strong>{{ report.low }}</strong><small>Cần đọc và xem xét nội dung</small></div></div>
      <div class="live-distribution" aria-label="Phân bố sao"><div v-for="star in [5,4,3,2,1]" :key="star"><span>{{ star }} sao</span><div aria-hidden="true"><i :style="{width:`${report.count?(report.distribution[star]||0)/report.count*100:0}%`}"></i></div><strong>{{ report.distribution[star]||0 }}</strong></div></div>
      <div class="live-table" tabindex="0" role="region" aria-label="Điểm đánh giá theo khóa học"><table><thead><tr><th>Khóa học</th><th>Điểm /5</th><th>Số đánh giá</th><th>Đã hoàn thành</th><th>Tỷ lệ phản hồi</th></tr></thead><tbody><tr v-for="course in visibleCourses" :key="course.courseId"><td>{{ course.courseName }}</td><td>{{ course.average===null?'Chưa đánh giá':course.average.toFixed(1) }}</td><td>{{ course.count }}</td><td>{{ course.completed }}</td><td>{{ course.responseRate===null?'—':`${Math.round(course.responseRate)}%` }}</td></tr></tbody></table></div>
      <TablePagination v-if="!printing" v-model:page="coursePage" v-model:page-size="coursePageSize" :total="courseRows.length" :page-count="coursePageCount" unit="khóa học" unit-label="Khóa học"/>
      <h4>{{ lowOnly?'Phản hồi cần chú ý':'Phản hồi mới nhất' }}</h4><p v-if="!report.feedback.length">{{ report.count?'Không có phản hồi phù hợp.':'Chưa có học viên đánh giá khóa học.' }}</p>
      <div class="live-feedback"><article v-for="item in report.feedback" :key="item.id"><div><strong>{{ item.learner }}</strong><span>{{ item.stars }} ★</span></div><small>{{ item.courseName }} · {{ new Date(item.updatedAt).toLocaleDateString('vi-VN') }}</small><p>{{ item.content||'Học viên chỉ chấm sao, không để lại nhận xét.' }}</p></article></div>
      <footer v-if="report.totalPages>1" class="feedback-pagination"><button class="btn btn-secondary" :disabled="page===0" @click="page--">Trước</button><span>Trang {{ page+1 }}/{{ report.totalPages }} · {{ report.totalFeedback }} phản hồi</span><button class="btn btn-secondary" :disabled="page+1>=report.totalPages" @click="page++">Sau</button></footer>
    </template>
  </section>
</template>
<script setup lang="ts">
import SkeletonLoader from "./SkeletonLoader.vue";
import { computed,ref,watch,onBeforeUnmount } from 'vue';
import TablePagination from './TablePagination.vue';
import { useTablePagination } from '../composables/useTablePagination';
import { Star } from 'lucide-vue-next';
import { courseRatingApi } from '../api/courseRatingApi';
import type { LiveRatingReport,RatingSummary } from '../api/courseRatingApi';
const props=withDefaults(defineProps<{printing?:boolean}>(),{printing:false});
const courseRows=ref<RatingSummary[]>([]);
const {page:coursePage,pageSize:coursePageSize,pageCount:coursePageCount,paginated:paginatedCourses,reset:resetCoursePage}=useTablePagination(courseRows);
const visibleCourses=computed(()=>props.printing?courseRows.value:paginatedCourses.value);
const courseId=ref(''),lowOnly=ref(false),page=ref(0),loading=ref(false),error=ref(''),report=ref<LiveRatingReport|null>(null),options=ref<RatingSummary[]>([]);
let sequence=0;
async function load(){const request=++sequence;loading.value=true;error.value='';report.value=null;try{const result=await courseRatingApi.report(courseId.value,lowOnly.value,page.value);if(request!==sequence)return;report.value=result;courseRows.value=result.courses;if(!courseId.value)options.value=result.courses;}catch(e){if(request===sequence)error.value=(e as {response?:{status?:number;data?:{message?:string}}}).response?.status===403?'Bạn chưa có quyền xem báo cáo đánh giá khóa học.':(e as {response?:{data?:{message?:string}}}).response?.data?.message||'Không thể tải dữ liệu đánh giá. Vui lòng thử lại.';}finally{if(request===sequence)loading.value=false;}}
function exportCsv(){if(!report.value)return;const escape=(value:string|number)=>`"${String(value).replace(/^[=+@\-\t\r]/,"'$&").replaceAll('"','""')}"`;const data=[['Khóa học','Điểm /5','Số đánh giá','Lượt hoàn thành','Tỷ lệ phản hồi (%)','Phản hồi 1–2 sao'],...report.value.courses.map(c=>[c.courseName,c.average===null?'Chưa đánh giá':c.average.toFixed(1),c.count,c.completed,c.responseRate===null?'—':c.responseRate.toFixed(1),c.low])];const url=URL.createObjectURL(new Blob(['\uFEFF'+data.map(row=>row.map(escape).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='danh-gia-khoa-hoc.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
watch(courseId,()=>{page.value=0;resetCoursePage();});watch([courseId,lowOnly,page],load,{immediate:true});onBeforeUnmount(()=>{sequence++;});
</script>
<style scoped>
.live-ratings{background:var(--bg-card);border:1px solid var(--border-color);border-radius:10px;padding:20px;margin:18px 0;min-width:0}header{display:flex;justify-content:space-between;gap:12px}header>svg{color:#b88723}h3{font-size:16px;margin:0 0 7px}h4{font-size:13px;margin:22px 0 14px}p{font-size:12px;line-height:1.7;color:var(--text-muted)}.rating-filters{display:flex;align-items:flex-end;flex-wrap:wrap;gap:12px;margin:20px 0 10px}.rating-filters label{display:flex;flex-direction:column;gap:7px;font-size:11px;min-width:0;max-width:100%}.rating-filters select{max-width:100%;border:1px solid var(--border-color);border-radius:6px;padding:10px;background:var(--bg-card);color:var(--text-main);font:inherit}.scope-note{font-size:10px;margin-bottom:16px}.live-kpis{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:20px 0}.live-kpis>div{background:var(--bg-subtle);border-radius:7px;padding:16px;display:flex;flex-direction:column;gap:8px}.live-kpis span{font-size:11px;color:var(--text-muted)}.live-kpis strong{font-size:28px}.live-kpis small{font-size:10px;color:var(--text-muted)}.live-distribution{max-width:500px;display:grid;gap:9px;margin:18px 0}.live-distribution>div{display:flex;align-items:center;gap:10px;font-size:11px}.live-distribution>div>span{width:35px}.live-distribution>div>div{height:8px;background:var(--bg-subtle);border-radius:4px;flex:1;overflow:hidden}.live-distribution i{display:block;height:100%;background:#d6a83f}.live-distribution strong{width:24px;text-align:right}.live-table{overflow:auto}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:11px}th,td{padding:12px;border-bottom:1px solid var(--border-color);text-align:left}th{background:var(--bg-subtle);color:var(--text-muted);font-weight:500}.live-feedback{display:grid;grid-template-columns:1fr 1fr;gap:12px}.live-feedback article{border:1px solid var(--border-color);border-radius:7px;padding:14px;min-width:0}.live-feedback article>div{display:flex;justify-content:space-between;gap:12px;font-size:12px}.live-feedback small{display:block;margin:8px 0;font-size:10px;color:var(--text-muted)}.rating-error{color:var(--danger-ink);background:var(--danger-surface);padding:12px;border-radius:7px}.feedback-pagination{display:flex;gap:12px;align-items:center;justify-content:flex-end;margin-top:18px;font-size:11px}@media(max-width:600px){.live-ratings{padding:16px}.live-kpis{grid-template-columns:1fr}.live-feedback{grid-template-columns:1fr}.rating-filters label{width:100%}.rating-filters select{width:100%}.feedback-pagination{flex-wrap:wrap}}@media print{.rating-filters button,footer button{display:none}.live-table{overflow:visible}table{white-space:normal}.live-feedback article{break-inside:avoid}}
</style>
